CREATE TABLE adjustment_keys(business_id TEXT NOT NULL REFERENCES businesses(id),key TEXT NOT NULL,PRIMARY KEY(business_id,key));
CREATE TABLE invoice_reversals(business_id TEXT NOT NULL,invoice_id TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(business_id,invoice_id),FOREIGN KEY(business_id,invoice_id) REFERENCES invoices(business_id,id));
CREATE TRIGGER reversal_guard BEFORE INSERT ON invoice_reversals BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM invoices WHERE business_id=NEW.business_id AND id=NEW.invoice_id AND status='final' AND paid=0) THEN RAISE(ABORT,'Only unpaid final invoices support reversal') END;
 UPDATE products SET cost=CASE WHEN stock+(SELECT SUM(quantity) FROM invoice_items WHERE business_id=NEW.business_id AND invoice_id=NEW.invoice_id AND product_id=products.id)>0 THEN CAST(ROUND((cost*stock+(SELECT SUM(quantity*cost) FROM invoice_items WHERE business_id=NEW.business_id AND invoice_id=NEW.invoice_id AND product_id=products.id))*1.0/(stock+(SELECT SUM(quantity) FROM invoice_items WHERE business_id=NEW.business_id AND invoice_id=NEW.invoice_id AND product_id=products.id))) AS INTEGER) ELSE cost END,stock=stock+(SELECT SUM(quantity) FROM invoice_items WHERE business_id=NEW.business_id AND invoice_id=NEW.invoice_id AND product_id=products.id),version=version+1 WHERE business_id=NEW.business_id AND kind='product' AND id IN(SELECT product_id FROM invoice_items WHERE business_id=NEW.business_id AND invoice_id=NEW.invoice_id);
 INSERT INTO inventory_movements(business_id,product_id,quantity,reason,reference) SELECT i.business_id,i.product_id,i.quantity,'invoice reversal',NEW.invoice_id FROM invoice_items i JOIN products p ON p.business_id=i.business_id AND p.id=i.product_id WHERE i.business_id=NEW.business_id AND i.invoice_id=NEW.invoice_id AND p.kind='product';
 UPDATE invoices SET status='void' WHERE business_id=NEW.business_id AND id=NEW.invoice_id;
END;
